!function(){"use strict";app.directive("btnDataAdicionalArticulo",(function(modalService,nombreModal){return{restrict:"A",scope:{entity:"=",getDataEtiqueta:"&",datosAdicionales:"="},link:function(scope,element,attrs){element.on("click",(async function(){if(!Number.isInteger(scope.entity.cantidad))return void Swal.fire({title:"Datos Adicionales",icon:"warning",html:"El valor de la cantidad del artículo tiene que ser un número entero!"});let{fileCtrl:fileCtrl,controller:controller,template:template}=nombreModal.compra.MODAL_DATO_ADICIONAL_ARTICULO,ctrl=(await import(fileCtrl))[controller],modalRef;modalService.openModalCustom({controller:ctrl,template:template,size:"lg",params:{entity:scope.entity,datosAdicionales:scope.datosAdicionales},isRenderRazorPartial:!0}).result.then((function(results){if(angular.isArray(results)){if(scope.datosAdicionales.some(item=>item.idArticulo===scope.entity.idArticulo)){scope.datosAdicionales=scope.datosAdicionales.filter(item=>item.idArticulo!==scope.entity.idArticulo);for(let item of results)scope.datosAdicionales.push(item)}else for(let item of results)scope.datosAdicionales.push(item);console.log(scope.datosAdicionales)}}))}))}}}))}(window.angular);